fn delete(line: &mut Vec<char>, l: usize, at: usize, p: usize) {
    // Preconditions:
    // 0 <= l <= line.len()
    // 0 <= at, 0 <= p, at + p <= l

    // Shift the range [at+p, l) down to start at `at`.
    line.copy_within(at + p .. l, at);
    // Truncate off the last p characters (and anything beyond `l`).
    line.truncate(l - p);
}

#[cfg(test)]
mod tests {
    use super::delete;

    #[test]
    fn delete_middle() {
        let mut v: Vec<char> = "abcdefg".chars().collect();
        // delete 2 chars at index 2 from the first 5 chars ("abcde")
        // => keep "ab" + "de" = "abde"
        delete(&mut v, 5, 2, 2);
        assert_eq!(v.iter().collect::<String>(), "abdeg");
        // note: "g" was beyond l=5, so it gets dropped by truncate
        v.truncate(4);
        assert_eq!(v.iter().collect::<String>(), "abde");
    }

    #[test]
    fn delete_prefix() {
        let mut v: Vec<char> = "rustlang".chars().collect();
        // delete the first 4 of the first 6 chars: "rustla" -> remove "rust"
        delete(&mut v, 6, 0, 4);
        assert_eq!(v.iter().collect::<String>(), "lang");
    }

    #[test]
    fn delete_suffix_of_prefix() {
        let mut v: Vec<char> = "hello world".chars().collect();
        // delete last 3 of the first 8 chars: "hello wo" -> remove " wo"
        delete(&mut v, 8, 5, 3);
        assert_eq!(v.iter().collect::<String>(), "hellorld");
    }

    #[test]
    fn delete_nothing() {
        let mut v: Vec<char> = "xyz".chars().collect();
        // p = 0: just truncate to l
        delete(&mut v, 2, 1, 0);
        assert_eq!(v.iter().collect::<String>(), "xy");
    }
}